import type { AnchorHTMLAttributes } from 'react';
import './hover-lift-card.css';

/** A linked card that rises on hover and on keyboard focus. */
export function HoverLiftCard({
  className = '',
  children,
  ...rest
}: AnchorHTMLAttributes<HTMLAnchorElement>) {
  return (
    <a className={`mg-lift ${className}`} {...rest}>
      {children}
    </a>
  );
}

.mg-lift {
  display: block;
  padding: 20px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 14px;
  background: #121212;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
  color: var(--mg-text, #ffffff);
  text-decoration: none;
  transition:
    transform 240ms cubic-bezier(0.2, 0.7, 0.2, 1),
    box-shadow 240ms cubic-bezier(0.2, 0.7, 0.2, 1),
    border-color 240ms ease;
}

.mg-lift:hover,
.mg-lift:focus-visible {
  border-color: var(--mg-accent-text, #648aff);
  box-shadow: 0 18px 36px -14px rgba(0, 71, 255, 0.45);
  transform: translateY(-6px);
}

.mg-lift:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 3px;
}

.mg-lift:active {
  transform: translateY(-2px);
}

@media (prefers-reduced-motion: reduce) {
  .mg-lift,
  .mg-lift:hover,
  .mg-lift:focus-visible,
  .mg-lift:active {
    transform: none;
    transition: none;
  }
}
